const FIELDS = ["people", "culture", "food", "heritage", "historic", "wildlife"];

export function cultureFor(iso) {
  const row = CULTURE[iso];
  if (!row) return null;
  const out = {};
  FIELDS.forEach((k, i) => {
    out[k] = row[i];
  });
  return out;
}

